public static final String GRADIENT_STROKE_SHADER_STRING_HEAD = "
    layout(color) uniform half4 u_color;
    uniform float u_width;
    uniform float u_corner;
    uniform float u_weight;
    uniform float u_ratio;
    uniform float2 u_size;
    uniform float2 u_padding;
    // 线段线段（分为Near端与Far端）渐变参数
    // 对角线段宽度
    uniform float u_nearLineWidth;
    uniform float u_farLineWidth;
    // 对角线段最大alpha
    uniform float u_nearLineAlpha;
    uniform float u_farLineAlpha;
    // 对角线段横向渐变比例
    uniform float2 u_nearLineFadeToSides;
    uniform float2 u_farLineFadeToSides;
    // 对角线段纵向渐变比例
    uniform float2 u_nearLineFadeTowardsCenter;
    uniform float2 u_farLineFadeTowardsCenter;
    const float PI = 2.0 * asin(1.0);";

public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_BASE = "
    float RBox(float2 p,float2 b,float r){
        float2 q=abs(p)-b+r;
        return min(max(q.x,q.y),0.)+length(max(q,0.))-r;
    }";

public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_BEZIER = "
    float cubicBezierDistance(vec2 p, vec2 p0, vec2 p1, vec2 p2, vec2 p3) {
        // 将贝塞尔转换为幂基形式：B(t) = c0 + c1 t + c2 t^2 + c3 t^3
        vec2 c0 = p0;
        vec2 c1 = 3.0 * (p1 - p0);
        vec2 c2 = 3.0 * (p2 - 2.0 * p1 + p0);
        vec2 c3 = p3 - 3.0 * p2 + 3.0 * p1 - p0;

        float t = 0.5; // 初始值
        for (int i = 0; i < 10; i++) {
            vec2 Bt   = ((c3 * t + c2) * t + c1) * t + c0;
            vec2 dBt  = (3.0 * c3 * t + 2.0 * c2) * t + c1;
            vec2 ddBt = 6.0 * c3 * t + 2.0 * c2;
            vec2 r    = Bt - p;
            // E(t) = |B(t)-p|^2 的一阶、二阶导
            float f1 = dot(dBt, r);
            float f2 = dot(ddBt, r) + dot(dBt, dBt);
            // 避免除零
            float denom = max(f2, 1e-4);
            t = clamp(t - f1 / denom, 0.0, 1.0);
        }
        vec2 Bt = ((c3 * t + c2) * t + c1) * t + c0;
        vec2 re = Bt - p;

        // 计算曲线在最近点处的切线向量
        vec2 tangent = (3.0 * c3 * t + 2.0 * c2) * t + c1;

        // 计算法向量（切线逆时针旋转90度）
        vec2 normal = vec2(-tangent.y, tangent.x);

        // 归一化法向量
        vec2 normalizedNormal = normalize(normal);

        // 计算有符号距离
        float dis = length(re);
        float signedDistance = dot(re, normalizedNormal) > 0.0 ? dis : -dis;

        return signedDistance ;
    }
    float sdBezierDistance(vec2 p, vec2 b, float cc) {
        float sdf = 0.0;
        if(any(lessThanEqual(abs(p), b - cc))) {
            sdf = RBox(p, b, cc);
        }else{
            float point  = max(cc*u_weight*0.5,0.001);
            sdf = cubicBezierDistance(abs(p)-b+cc,vec2(cc, 0.0), vec2(cc, point), vec2(point, cc),vec2(0.0, cc));
        }
        return sdf;
    }
";

public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_SMOOTH = "
    float approx_sdSquircle(vec2 p, float n){
        // symmetries
        p = abs(p); // if( p.y>p.x ) p=p.yx;
        float w = pow(p.x,n) + pow(p.y,n);

        // linearlized implicit (taylor)
        float b = 2.0*n-2.0;
        float a = 1.0-1.0/n;
        return (w-pow(w,a)) * inversesqrt(pow(p.x,b)+pow(p.y,b));
    }

    float opSmoothIntersectionOne(float d1,float d2){
        float h=clamp(.5-.5*(d2-d1),0.,1.);
        return mix(d2,d1,h) + h*(1.-h);
    }
    vec2 getPreCalcMA() {
        float halfSizeX = u_size.x * 0.5;
        float halfSizeY = u_size.y * 0.5;
        float maX = 0.0;
        float maY = 0.0;
        if (halfSizeX > halfSizeY) {
            maX = halfSizeX;
            maY = halfSizeY * 0.5;
        } else {
            maX = halfSizeX * 0.5;
            maY = halfSizeY;
        }
        return vec2(maX, maY);
    }

    vec2 sdRoundedBoxMerge(vec2 p,  vec2 b,  float cr){
        vec2 q1 = abs(p)-b;
        float r1 = min(max(q1.x,q1.y),0.0) + length(max(q1,0.0));
        vec2 q2 = q1 + cr;
        float r2 = min(max(q2.x,q2.y),0.0) + length(max(q2,0.0)) - cr;
        float h=clamp(.5-.5*(r2-r1),0.,1.);
        return vec2(mix(r2,r1,h)+h*(1.-h), r2);
    }

    float sdSquircle(vec2 p, in vec2 b, float cc) {
        float sdf = 0.0;
        float sc =  cc + u_weight * cc;
        float rbRes = 0.0;
        if(any(lessThan(abs(p), b - sc))) {
            vec2 res = sdRoundedBoxMerge(p, b, cc);
            sdf = res.x;
            rbRes = res.y;
        } else {
            vec2 sp = (abs(p) - b + sc) / sc;
            float angle = abs(atan(sp.y, sp.x) - 0.785398); // 0.785398 for 45 degree
            float preCalcN1Delta = 3.02 + u_weight * 2.44;
            float preCalcN2Delta = 2.05 + u_weight * 2.44;
            float sn = mix(preCalcN1Delta, preCalcN2Delta, smoothstep(22.0, 0.0, degrees(angle)));
            sdf = approx_sdSquircle(sp, sn) * sc;
            rbRes = RBox(p, b, cc);
            sdf = opSmoothIntersectionOne(sdf, rbRes);
        }

        if((u_corner) == min(b.x, b.y)) {
            float sdfRect = RBox(p, getPreCalcMA(), 0);
            sdf = min(max(sdfRect, rbRes), sdf);
        }

        // return smoothstep(0.0, -antiAliasing, sdf);
        return sdf;
    }";

public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_PART_1 = "
    float getDis(float2 pos,float2 halfsize){
        float2 rect=abs(pos-halfsize);
        return rect.x+rect.y;
    }
    float3 getLineFadeTowardCenter(float2 u_lineFadeTowardsCenter, float lineWidth) {
        float x = clamp(u_lineFadeTowardsCenter.x, 0.0, 1.0);
        float y = clamp(u_lineFadeTowardsCenter.y, 0.0, 1.0 - x);
        float z = clamp((1.0 - x - y), 0.01, 1.0);
        float3 lineFadeTowardsCenter = lineWidth * float3(x, y, z);
        lineFadeTowardsCenter.y += lineFadeTowardsCenter.x;
        lineFadeTowardsCenter.z += lineFadeTowardsCenter.y;
        lineFadeTowardsCenter *= -1.;
        return lineFadeTowardsCenter;
    }

    half4 gradientStrokeColorWithRatio(float2 fragCoord) {
        float ratio = u_ratio;

        float2 rectSize = u_size - u_padding * 2.0;
        float2 halfSize = rectSize / 2.0;
        float2 pos = fragCoord - u_size / 2.0;
        float2 dir_pos= normalize(pos);
        float2 dirAbs_pos = abs(dir_pos);
        float2 pos_n = min(float2(dirAbs_pos.xy*halfSize.yx/max(vec2(.001),dirAbs_pos.yx)),halfSize)*sign(dir_pos);

        float2 halfSize_symobol = float2(-halfSize.y,halfSize.x);
        float flag = mix(-1.0,1.0, step(ratio,0.5))*dot(halfSize_symobol,pos_n);

        float distanceAll= rectSize.x + rectSize.y;
        float dis_point = distanceAll*min(ratio,1.0-ratio)*2.0;
        float dis_pos = getDis(pos_n,halfSize);

        float distance_near = mix(dis_point+dis_pos,abs(dis_point-dis_pos),step(0.,flag));

        distance_near=min(2.*distanceAll-distance_near,distance_near);

        float2 nearLineFade = float2(u_nearLineFadeToSides.x, u_nearLineFadeToSides.x + u_nearLineFadeToSides.y);
        float2 farLineFade = float2(u_farLineFadeToSides.x, u_farLineFadeToSides.x + u_farLineFadeToSides.y);
        float lineNearAlpha = u_nearLineAlpha*smoothstep(nearLineFade.y*distanceAll, nearLineFade.x*distanceAll, distance_near);
        float lineFarAlpha = u_farLineAlpha*smoothstep(farLineFade.y*distanceAll, farLineFade.x*distanceAll, distanceAll-distance_near);

        float3 farLineFadeTowardsCenter = getLineFadeTowardCenter(u_farLineFadeTowardsCenter, u_farLineWidth);
        float3 nearLineFadeTowardsCenter = getLineFadeTowardCenter(u_nearLineFadeTowardsCenter, u_nearLineWidth);

        float corner = min(u_corner, min(halfSize.x, halfSize.y));";

public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_PART_3 = "
        float lineNearSdf = smoothstep(0., nearLineFadeTowardsCenter.x ,rectSdf)-smoothstep(nearLineFadeTowardsCenter.y,nearLineFadeTowardsCenter.z,rectSdf);
        float lineFarSdf = smoothstep(0., farLineFadeTowardsCenter.x, rectSdf)-smoothstep(farLineFadeTowardsCenter.y,farLineFadeTowardsCenter.z,rectSdf);
        lineNearAlpha *= lineNearSdf;
        lineFarAlpha *= lineFarSdf;

        float lineAlpha = clamp(lineNearAlpha + lineFarAlpha, 0.0, 1.0);
        return half4(u_color.xyz * lineAlpha, lineAlpha);
    }
    half4 main(float2 fragCoord) {
        return gradientStrokeColorWithRatio(fragCoord);
    }
";
